{"path":"/app/strategy.py","content":""""Player strategy for the 10x10 knight-enemy survival game."""

import json

GRID_SIZE = 10
# Direction encoding used by the game server: 0 up, 1 right, 2 down, 3 left.
USER_MOVES = ((-1, 0), (0, 1), (1, 0), (0, -1))
# Enemy moves in exactly this order, as recovered from run_game.cpython-313.pyc.
KNIGHT_MOVES = ((-2, -1), (-2, 1), (-1, -2), (-1, 2),
                (1, -2), (1, 2), (2, -1), (2, 1))
_POLICY = None


def _request(sock, text):
    sock.send(text.encode("utf-8"))
    data = sock.recv(1024).decode("utf-8")
    return json.loads(data)


def _valid(pos):
    return 0 <= pos[0] < GRID_SIZE and 0 <= pos[1] < GRID_SIZE


def _enemy_next(enemy, user):
    best_pos = None
    best_dist = float("inf")
    for dr, dc in KNIGHT_MOVES:
        candidate = (enemy[0] + dr, enemy[1] + dc)
        if _valid(candidate):
            dist = abs(candidate[0] - user[0]) + abs(candidate[1] - user[1])
            if dist < best_dist:
                best_dist = dist
                best_pos = candidate
    return best_pos


def _transition(state, direction):
    user, enemy = state
    dr, dc = USER_MOVES[direction]
    new_user = (user[0] + dr, user[1] + dc)
    if not _valid(new_user) or new_user == enemy:
        return None
    new_enemy = _enemy_next(enemy, new_user)
    if new_enemy == new_user:
        return None
    return new_user, new_enemy


def _build_policy():
    states = [((ur, uc), (er, ec))
              for ur in range(GRID_SIZE) for uc in range(GRID_SIZE)
              for er in range(GRID_SIZE) for ec in range(GRID_SIZE)
              if (ur, uc) != (er, ec)]

    # Greatest fixed point: states from which there is a move that remains in
    # the safe set forever.  The initial state is in this set and the resulting
    # policy quickly enters a safe cycle.
    winning = set(states)
    policy = {}
    while True:
        new_winning = set()
        new_policy = {}
        for state in states:
            if state not in winning:
                continue
            for direction in range(4):
                nxt = _transition(state, direction)
                if nxt in winning:
                    new_winning.add(state)
                    new_policy[state] = direction
                    break
        if new_winning == winning:
            return new_policy
        winning = new_winning
        policy = new_policy


def STRATEGY(client_socket):
    """Make exactly one safe move for the current turn."""
    global _POLICY
    if _POLICY is None:
        _POLICY = _build_policy()

    user_resp = _request(client_socket, "get_user_pos")
    enemy_resp = _request(client_socket, "get_enemy_pos")
    user = tuple(user_resp["position"])
    enemy = tuple(enemy_resp["position"])
    state = (user, enemy)

    direction = _POLICY.get(state)
    if direction is None:
        # Fallback should not be needed for the supplied game, but if reached,
        # choose the legal move maximizing post-enemy-move distance.
        choices = []
        for d in range(4):
            nxt = _transition(state, d)
            if nxt is not None:
                nu, ne = nxt
                choices.append((abs(nu[0] - ne[0]) + abs(nu[1] - ne[1]), d))
        direction = max(choices)[1]

    _request(client_socket, f"move {direction}")
